// ─── File: NoConsumerDemo.java ───
// Runnable demo: records are retained with no consumer; late consumers read them.
package com.bank.noconsumer.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class NoConsumerDemo {
    private static final Logger log = Logger.getLogger(NoConsumerDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long now = 100;
        // Retention window = 50 time units (delete policy)
        DurableLog logTopic = new DurableLog("transfers", 50);

        // Producer writes with NO consumer subscribed — records are still stored
        log.info(() -> "No consumer subscribed yet — producing anyway");
        logTopic.append(new TransferEvent("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")), 40); // old
        logTopic.append(new TransferEvent("TXF-2", "SAV2001", "CUR3001", new BigDecimal("12000")), 70);
        logTopic.append(new TransferEvent("TXF-3", "CUR3001", "SAV2001", new BigDecimal("8000")), 90);

        // Retention runs at now=100, cutoff = 50 => TXF-1 (@40) ages out
        logTopic.runRetention(now);

        // Fraud team comes online LATE as a NEW group with auto.offset.reset=earliest
        log.info(() -> "Fraud consumer subscribes now (earliest) — reads the backlog");
        new EarliestConsumer("fraud").subscribeAndRead(logTopic);

        // A new transfer arrives after both consumers exist
        logTopic.append(new TransferEvent("TXF-4", "SAV2001", "CUR3001", new BigDecimal("3000")), 101);

        // Dashboard comes online as a NEW group with auto.offset.reset=latest
        log.info(() -> "Dashboard consumer subscribes (latest) — only new events");
        new LatestConsumer("dashboard").subscribeAndRead(logTopic);
    }
}

