class DurableLog {
    private static final Logger log = Logger.getLogger(DurableLog.class.getName());
    private final String topic;
    private final long retentionWindow;
    private final List<TransferEvent> records = new ArrayList<>();
    private final List<Long> timestamps = new ArrayList<>();
    DurableLog(String topic, long retentionWindow) {
        this.topic = topic; this.retentionWindow = retentionWindow;
    }
    // Append succeeds regardless of consumers — write is independent of readers
    void append(TransferEvent e, long ts) {
        records.add(e); timestamps.add(ts);
        long off = records.size() - 1;
        log.info(() -> "[" + topic + "] STORED at offset " + off + " (ts=" + ts + ") " + e);
    }
    void runRetention(long now) {
        long cutoff = now - retentionWindow;
        Iterator<TransferEvent> ri = records.iterator();
        Iterator<Long> ti = timestamps.iterator();
        while (ri.hasNext()) {
            TransferEvent e = ri.next(); long ts = ti.next();
            if (ts < cutoff) {
                ri.remove(); ti.remove();
                log.info(() -> "[" + topic + "] RETENTION removed aged-out " + e
                        + " (ts=" + ts + " < cutoff=" + cutoff + ")");
            }
        }
    }
    int endOffset() { return records.size(); }
    TransferEvent at(int offset) { return records.get(offset); }
}

// ─── Would be in EarliestConsumer.java ───
class EarliestConsumer {
    private static final Logger log = Logger.getLogger(EarliestConsumer.class.getName());
    private final String group;
    EarliestConsumer(String group) { this.group = group; }
    // New group, no committed offset, auto.offset.reset=earliest -> read from 0
    void subscribeAndRead(DurableLog topic) {
        for (int off = 0; off < topic.endOffset(); off++) {
            int o = off;
            log.info(() -> "[" + group + "/earliest] read offset " + o + " -> " + topic.at(o));
        }
    }
}

// ─── Would be in LatestConsumer.java ───
class LatestConsumer {
    private static final Logger log = Logger.getLogger(LatestConsumer.class.getName());
    private final String group;
    LatestConsumer(String group) { this.group = group; }
    // New group, auto.offset.reset=latest -> start at current end, skip backlog
    void subscribeAndRead(DurableLog topic) {
        int start = topic.endOffset(); // only records produced AFTER this point
        log.info(() -> "[" + group + "/latest] starting at end offset " + start
                + " — backlog skipped (would read only future records)");
    }
}

